import type { Effect } from "./index.js"
import type * as Sink from "./Sink.js"

export interface Stream<A> {
  pipe<B>(first: (self: Stream<A>) => B): B
  pipe<B, C>(first: (self: Stream<A>) => B, second: (self: B) => C): C
  pipe<B, C, D>(first: (self: Stream<A>) => B, second: (self: B) => C, third: (self: C) => D): D
}
export declare const make: <A>(...values: ReadonlyArray<A>) => Stream<A>
export declare const empty: Stream<never>
export declare const succeed: <A>(value: A) => Stream<A>
export declare const fromArray: <A>(values: ReadonlyArray<A>) => Stream<A>
export declare const fromIterable: <A>(values: Iterable<A>) => Stream<A>
export declare const flatMap: <A, B>(f: (value: A) => Stream<B>) => (self: Stream<A>) => Stream<B>
export declare const fromArrays: <A>(...values: ReadonlyArray<ReadonlyArray<A>>) => Stream<A>
export declare const fromEffectRepeat: <A>(effect: Effect.Effect<A>) => Stream<A>
export declare const take: { <A>(count: number): (self: Stream<A>) => Stream<A>; <A>(self: Stream<A>, count: number): Stream<A> }
export declare const map: <A, B>(f: (value: A) => B) => (self: Stream<A>) => Stream<B>
export declare const filter: <A>(predicate: (value: A) => boolean) => (self: Stream<A>) => Stream<A>
export declare const tap: <A, B>(f: (value: A) => Effect.Effect<B>) => (self: Stream<A>) => Stream<A>
export declare const collect: <A>(self: Stream<A>) => Stream<Array<A>>
export declare const runCollect: <A>(self: Stream<A>) => Effect.Effect<Array<A>>
export declare const run: { <A>(sink: Sink.Sink<A>): <B>(self: Stream<B>) => Effect.Effect<A>; <A, B>(self: Stream<B>, sink: Sink.Sink<A>): Effect.Effect<A> }
export declare const runDrain: <A>(self: Stream<A>) => Effect.Effect<void>
